INSERT INTO `service_packages_i18n` (`id`, `package_id`, `locale`, `title`, `description`, `features`, `cta_label`) VALUES
('32000001-0000-4000-8000-0101861468', '32000000-0000-4000-8000-0101861468', 'tr', 'TEMEL — 20.000 ₺', 'Tek sektör için lead bulma + takip paneli. Seçtiğiniz 1 kanaldan (Amazon, B2B dizin veya fuar) ICP eşleşm', '["Lead(müşteri adayı) sayısı: 100 lead","Çalışma Saati: 40 saat","Biçimlendirme ve Temizleme","Lead Kontrolü: Yok"]', 'Teklif al'),
('32000002-0000-4000-8000-0101861468', '32000000-0000-4000-8000-0101861468', 'en', 'BASIC — 20,000 ₺', 'Lead generation + tracking dashboard for a single industry. ICP matching from one channel of your choice (Amazon, B2B directory or trade fairs).', '["Lead(müşteri adayı) sayısı: 100 lead","Çalışma Saati: 40 saat","Biçimlendirme ve Temizleme","Lead Kontrolü: Yok"]', 'Request offer'),
('32000001-0000-4000-8000-0102861468', '32000000-0000-4000-8000-0102861468', 'tr', 'STANDART — 30.000 ₺', 'TEMEL''in tümü + 2 kaynaktan 300 aday, churn risk skoru, pazar sinyalleri (rakip site/fiyat takibi), karar', '["Lead(müşteri adayı) sayısı: 200","Çalışma Saati: 50","Biçimlendirme ve Temizleme","Lead Kontrolü"]', 'Teklif al'),
('32000002-0000-4000-8000-0102861468', '32000000-0000-4000-8000-0102861468', 'en', 'STANDARD — 30,000 ₺', 'Everything in BASIC + 300 prospects from 2 sources, churn risk scoring, market signals (competitor site/price tracking) and decision-maker email discovery.', '["Lead(müşteri adayı) sayısı: 200","Çalışma Saati: 50","Biçimlendirme ve Temizleme","Lead Kontrolü"]', 'Request offer'),
('32000001-0000-4000-8000-0103861468', '32000000-0000-4000-8000-0103861468', 'tr', 'PRO — 50.000 ₺', 'STANDART''ın tümü + 3 kaynaktan 1000 aday, otomatik scraper sinyalleri, AI outreach e-posta taslağı, ERP/C', '["Lead(müşteri adayı) sayısı: 1000","Çalışma Saati: 50","Biçimlendirme ve Temizleme","Lead Kontrolü"]', 'Teklif al'),
('32000002-0000-4000-8000-0103861468', '32000000-0000-4000-8000-0103861468', 'en', 'PRO — 50,000 ₺', 'Everything in STANDARD + 1,000 prospects from 3 sources, automated scraper signals, AI outreach email drafts and ERP/CRM integration.', '["Lead(müşteri adayı) sayısı: 1000","Çalışma Saati: 50","Biçimlendirme ve Temizleme","Lead Kontrolü"]', 'Request offer'),
('32000001-0000-4000-8000-0201861494', '32000000-0000-4000-8000-0201861494', 'tr', 'TEMEL — 15.000 ₺', 'Tek marka için 2 platforma (örn. Instagram + Facebook) zamanlanmış yayın ve içerik takvimi paneli. ', '["Sayfa/Kanal Değerlendirmesi"]', 'Teklif al'),
('32000002-0000-4000-8000-0201861494', '32000000-0000-4000-8000-0201861494', 'en', 'BASIC — 15,000 ₺', 'Scheduled publishing and content calendar dashboard for a single brand on 2 platforms (e.g. Instagram + Facebook).', '["Sayfa/Kanal Değerlendirmesi"]', 'Request offer'),
('32000001-0000-4000-8000-0202861494', '32000000-0000-4000-8000-0202861494', 'tr', 'STANDART — 25.000 ₺', 'TEMEL''in tümü + 4 platform, 3 marka/hesap, AI içerik asistanı (metin & hashtag), ', '["Sayfa/Kanal Değerlendirmesi"]', 'Teklif al'),
('32000002-0000-4000-8000-0202861494', '32000000-0000-4000-8000-0202861494', 'en', 'STANDARD — 25,000 ₺', 'Everything in BASIC + 4 platforms, 3 brands/accounts and an AI content assistant (copy & hashtags).', '["Sayfa/Kanal Değerlendirmesi"]', 'Request offer'),
('32000001-0000-4000-8000-0203861494', '32000000-0000-4000-8000-0203861494', 'tr', 'PRO — 45.000 ₺', 'STANDART''ın tümü + 6+ platform (Ads dahil), sınırsız marka/hesap, çoklu kullanıcı & rol yönetimi, GA4/Ads', '["Sayfa/Kanal Değerlendirmesi"]', 'Teklif al'),
('32000002-0000-4000-8000-0203861494', '32000000-0000-4000-8000-0203861494', 'en', 'PRO — 45,000 ₺', 'Everything in STANDARD + 6+ platforms (Ads included), unlimited brands/accounts, multi-user & role management and GA4/Ads reporting.', '["Sayfa/Kanal Değerlendirmesi"]', 'Request offer'),
('32000001-0000-4000-8000-0301850998', '32000000-0000-4000-8000-0301850998', 'tr', 'Temel analiz', 'Analiz hizmeti bulgular + aksiyon planı içerir. ', '[]', 'Teklif al'),
('32000002-0000-4000-8000-0301850998', '32000000-0000-4000-8000-0301850998', 'en', 'Essential Audit', 'The audit includes findings plus an action plan.', '[]', 'Request offer'),
('32000001-0000-4000-8000-0401861502', '32000000-0000-4000-8000-0401861502', 'tr', 'Tahmin Paneli', 'Tek veri seti için 1 ML tahmin modeli (regresyon/sınıflandırma) + güven aralığı, sonuç tablosu ve temel g', '["Model Dokümantasyonu"]', 'Teklif al'),
('32000002-0000-4000-8000-0401861502', '32000000-0000-4000-8000-0401861502', 'en', 'Forecasting Dashboard', 'One ML forecasting model (regression/classification) for a single dataset + confidence intervals, results table and basic visualizations.', '["Model Dokümantasyonu"]', 'Request offer'),
('32000001-0000-4000-8000-0402861502', '32000000-0000-4000-8000-0402861502', 'tr', 'ML Analiz Sistemi', 'TEMEL''in tümü + 3 model, model versiyonlama (MLflow), gelişmiş görselleştirme (Manhattan/PCA/dağılım), CS', '["Model Dokümantasyonu"]', 'Teklif al'),
('32000002-0000-4000-8000-0402861502', '32000000-0000-4000-8000-0402861502', 'en', 'ML Analytics System', 'Everything in BASIC + 3 models, model versioning (MLflow), advanced visualizations (Manhattan/PCA/distribution) and CSV/VCF import.', '["Model Dokümantasyonu"]', 'Request offer'),
('32000001-0000-4000-8000-0403861502', '32000000-0000-4000-8000-0403861502', 'tr', 'Tam AI Platform', 'STANDART''ın tümü + sınırsız model, otomatik yeniden eğitim döngüsü, AI/LLM yorum katmanı, sıralama/seçim ', '["Model Dokümantasyonu"]', 'Teklif al'),
('32000002-0000-4000-8000-0403861502', '32000000-0000-4000-8000-0403861502', 'en', 'Full AI Platform', 'Everything in STANDARD + unlimited models, automated retraining loop, AI/LLM interpretation layer and ranking/selection index.', '["Model Dokümantasyonu"]', 'Request offer'),
('32000001-0000-4000-8000-0501861509', '32000000-0000-4000-8000-0501861509', 'tr', 'Scraping Paneli', 'Tek site/kategori için scraping + sonuçları listeleyen panel. Arama, ürün detayı ve ASIN tekilleştirme, ', '["Ticari Kaynak Kullanımı","Ön Analiz: Yok","Yönetici Özeti: Yok"]', 'Teklif al'),
('32000002-0000-4000-8000-0501861509', '32000000-0000-4000-8000-0501861509', 'en', 'Scraping Dashboard', 'Scraping for a single site/category + a dashboard listing the results. Search, product details and ASIN deduplication.', '["Ticari Kaynak Kullanımı","Ön Analiz: Yok","Yönetici Özeti: Yok"]', 'Request offer'),
('32000001-0000-4000-8000-0502861509', '32000000-0000-4000-8000-0502861509', 'tr', 'Skorlama Sistemi', 'TEMEL''in tümü + Keepa fiyat geçmişi, çok boyutlu risk/fırsat skorlama ve LLM destekli açıklanabilir karar', '["Ticari Kaynak Kullanımı","Ön Analiz: Yok","Yönetici Özeti: Yok"]', 'Teklif al'),
('32000002-0000-4000-8000-0502861509', '32000000-0000-4000-8000-0502861509', 'en', 'Scoring System', 'Everything in BASIC + Keepa price history, multi-dimensional risk/opportunity scoring and LLM-assisted explainable decisions.', '["Ticari Kaynak Kullanımı","Ön Analiz: Yok","Yönetici Özeti: Yok"]', 'Request offer'),
('32000001-0000-4000-8000-0503861509', '32000000-0000-4000-8000-0503861509', 'tr', 'Tam Karar Radarı', 'STANDART''ın tümü + 5 boyut skor, coverage gate (confidence honesty), tez izleme ve bozulma uyarısı, çoklu', '["Ticari Kaynak Kullanımı","Ön Analiz","Yönetici Özeti"]', 'Teklif al'),
('32000002-0000-4000-8000-0503861509', '32000000-0000-4000-8000-0503861509', 'en', 'Full Decision Radar', 'Everything in STANDARD + 5-dimension scoring, coverage gate (confidence honesty), thesis tracking with degradation alerts.', '["Ticari Kaynak Kullanımı","Ön Analiz","Yönetici Özeti"]', 'Request offer'),
('32000001-0000-4000-8000-0601861515', '32000000-0000-4000-8000-0601861515', 'tr', 'GEO + SEO Analiz', 'Sitenizin yapay zeka aramalarına hazırlık analizi: 6 boyutlu GEO+SEO skoru, AI platform hazırlığı, AI cra', '[]', 'Teklif al'),
('32000002-0000-4000-8000-0601861515', '32000000-0000-4000-8000-0601861515', 'en', 'GEO + SEO Audit', 'AI-search readiness analysis of your site: 6-dimension GEO+SEO score, AI platform readiness and AI crawler access review.', '[]', 'Request offer'),
('32000001-0000-4000-8000-0602861515', '32000000-0000-4000-8000-0602861515', 'tr', 'Analiz + Uygulama', 'TEMEL''in tümü + uygulama: Schema.org/JSON-LD, llms.txt, AI crawler erişimi düzeni, teknik SEO ve CWV iyil', '[]', 'Teklif al'),
('32000002-0000-4000-8000-0602861515', '32000000-0000-4000-8000-0602861515', 'en', 'Audit + Implementation', 'Everything in BASIC + implementation: Schema.org/JSON-LD, llms.txt, AI crawler access configuration, technical SEO and Core Web Vitals improvements.', '[]', 'Request offer'),
('32000001-0000-4000-8000-0603861515', '32000000-0000-4000-8000-0603861515', 'tr', 'Tam GEO + SEO + İzleme', 'STANDART''ın tümü + tüm site kapsamı, E-E-A-T ve marka anması çalışması, içerik uygulaması, 30/60/90 yol h', '[]', 'Teklif al'),
('32000002-0000-4000-8000-0603861515', '32000000-0000-4000-8000-0603861515', 'en', 'Full GEO + SEO + Monitoring', 'Everything in STANDARD + full-site coverage, E-E-A-T and brand mention (entity) work, content implementation and a 30/60/90-day roadmap.', '[]', 'Request offer'),
('32000001-0000-4000-8000-0701861532', '32000000-0000-4000-8000-0701861532', 'tr', 'GA4 + GTM Kurulum', 'Google Analytics 4 ve Google Tag Manager kurulumu, temel sayfa görüntüleme ve 1-2 dönüşüm olayı yapılandı', '[]', 'Teklif al'),
('32000002-0000-4000-8000-0701861532', '32000000-0000-4000-8000-0701861532', 'en', 'GA4 + GTM Setup', 'Google Analytics 4 and Google Tag Manager setup, with basic page-view tracking and configuration of 1–2 conversion events.', '[]', 'Request offer'),
('32000001-0000-4000-8000-0702861532', '32000000-0000-4000-8000-0702861532', 'tr', 'Dönüşüm İzleme', 'TEMEL''in tümü + Meta Pixel, Google Ads dönüşüm izleme, e-ticaret satın alma/gelir event''leri ve 5''e kadar', '[]', 'Teklif al'),
('32000002-0000-4000-8000-0702861532', '32000000-0000-4000-8000-0702861532', 'en', 'Conversion Tracking', 'Everything in BASIC + Meta Pixel, Google Ads conversion tracking, e-commerce purchase/revenue events and up to 5 conversion events.', '[]', 'Request offer'),
('32000001-0000-4000-8000-0703861532', '32000000-0000-4000-8000-0703861532', 'tr', 'Tam Tracking Sistemi', 'STANDART''ın tümü + Meta Conversions API (server-side), sGTM, Consent Mode v2 (KVKK/GDPR), kanal/atıf & RO', '[]', 'Teklif al'),
