('32000001-0000-4000-8000-0801861536', '32000000-0000-4000-8000-0801861536', 'tr', 'Tek Seferlik Veri', 'Tek site veya Google Maps aramasından ihtiyacınız olan verinin (isim, telefon, adres, fiyat vb.) çekilip ', '[]', 'Teklif al'),
('32000002-0000-4000-8000-0801861536', '32000000-0000-4000-8000-0801861536', 'en', 'One-Time Data Extraction', 'The data you need (name, phone, address, price, etc.) extracted from a single website or Google Maps search and delivered.', '[]', 'Request offer'),
('32000001-0000-4000-8000-0802861536', '32000000-0000-4000-8000-0802861536', 'tr', 'Özel Scraping Botu', '1-3 site için yeniden çalıştırılabilir özel scraping scripti: dinamik (JS) sayfa desteği, stealth, zamanl', '[]', 'Teklif al'),
('32000002-0000-4000-8000-0802861536', '32000000-0000-4000-8000-0802861536', 'en', 'Custom Scraping Bot', 'A re-runnable custom scraping script for 1–3 sites: dynamic (JS) page support, stealth mode and scheduling.', '[]', 'Request offer'),
